arguments.cmd:
apply_patch <<'PATCH'
*** Begin Patch
*** Add File: output/styles.css
+:root{
+  /* Brand palette (OKLCH tuned to match provided hex guidance) */
+  --gb-green: oklch(52% 0.16 154);
+  --gb-forest: oklch(34% 0.05 150);
+  --gb-cream: oklch(92% 0.06 78);
+  --gb-brown: oklch(34% 0.07 55);
+  --gb-brown-2: oklch(44% 0.08 55);
+  --gb-mint: oklch(86% 0.08 155);
+  --gb-ink: oklch(20% 0.02 150);
+
+  --bg: oklch(98% 0.01 90);
+  --surface: oklch(99% 0.01 90);
+  --surface-2: oklch(96% 0.02 90);
+  --border: oklch(86% 0.02 90);
+  --muted: oklch(50% 0.02 150);
+
+  --primary: var(--gb-green);
+  --primary-strong: oklch(46% 0.18 154);
+  --accent: var(--gb-cream);
+  --danger: oklch(56% 0.2 25);
+  --success: oklch(55% 0.17 150);
+
+  --shadow-sm: 0 6px 20px oklch(20% 0.02 150 / 0.08);
+  --shadow-md: 0 18px 50px oklch(20% 0.02 150 / 0.12);
+
+  --radius-sm: 12px;
+  --radius-md: 18px;
+  --radius-lg: 28px;
+
+  --space-1: 4px;
+  --space-2: 8px;
+  --space-3: 16px;
+  --space-4: 24px;
+  --space-5: 32px;
+  --space-6: 48px;
+  --space-7: 64px;
+  --space-8: 96px;
+
+  --container: 1200px;
+
+  --ease-out: cubic-bezier(.16,1,.3,1);
+  --dur-fast: 160ms;
+  --dur: 260ms;
+}
+
+*{box-sizing:border-box}
+html,body{height:100%}
+body{
+  margin:0;
+  font-family: Inter, system-ui, -apple-system, Segoe UI, Roboto, Arial, sans-serif;
+  color:var(--gb-ink);
+  background:
+    radial-gradient(1200px 600px at 15% -10%, oklch(90% 0.07 155 / .55), transparent 60%),
+    radial-gradient(900px 500px at 100% 0%, oklch(92% 0.07 78 / .55), transparent 55%),
+    var(--bg);
+  line-height:1.5;
+}
+
+h1,h2,h3{font-family:"Fraunces", ui-serif, Georgia, serif; letter-spacing:-0.02em; line-height:1.15; margin:0 0 var(--space-2)}
+p{margin:0 0 var(--space-3)}
+a{color:inherit}
+
+.skip-link{
+  position:absolute; left:-999px; top:var(--space-3);
+  background:var(--surface); border:1px solid var(--border);
+  padding:var(--space-2) var(--space-3); border-radius:999px;
+}
+.skip-link:focus{left:var(--space-3); z-index:9999}
+
+.container{max-width:var(--container); margin:0 auto; padding:0 var(--space-3)}
+
+.topbar{
+  position:sticky; top:0; z-index:50;
+  background: color-mix(in oklch, var(--surface) 92%, transparent);
+  backdrop-filter: blur(10px);
+  border-bottom:1px solid color-mix(in oklch, var(--border) 80%, transparent);
+}
+.nav{
+  display:flex; align-items:center; justify-content:space-between;
+  gap:var(--space-3); padding:14px 0;
+}
+
+.brand{
+  display:flex; align-items:center; gap:10px; text-decoration:none;
+}
+.brand-mark{
+  width:40px; height:40px; border-radius:14px;
+  background:
+    radial-gradient(14px 14px at 30% 30%, oklch(92% 0.08 78), transparent 60%),
+    radial-gradient(18px 18px at 70% 70%, oklch(78% 0.12 155), transparent 60%),
+    linear-gradient(145deg, var(--gb-forest), var(--primary));
+  box-shadow: var(--shadow-sm);
+}
+.brand-name{display:flex; flex-direction:column}
+.brand-name strong{font-weight:750; letter-spacing:-0.02em}
+.brand-name span{font-size:12px; color:var(--muted)}
+
+.nav-links{display:flex; align-items:center; gap:10px}
+.nav-links a{
+  text-decoration:none; padding:10px 12px; border-radius:999px;
+  color: color-mix(in oklch, var(--gb-ink) 86%, var(--muted));
+}
+.nav-links a[aria-current="page"]{
+  background: color-mix(in oklch, var(--primary) 14%, var(--surface));
+  border:1px solid color-mix(in oklch, var(--primary) 20%, var(--border));
+  color: var(--gb-ink);
+}
+.nav-links a:hover{background: color-mix(in oklch, var(--surface-2) 70%, transparent)}
+.nav-actions{display:flex; align-items:center; gap:10px}
+
+.btn{
+  border:1px solid transparent;
+  background: var(--gb-ink);
+  color:white;
+  padding:12px 16px;
+  border-radius:999px;
+  font-weight:650;
+  letter-spacing:-0.01em;
+  text-decoration:none;
+  display:inline-flex;
+  align-items:center;
+  gap:10px;
+  cursor:pointer;
+  transition: transform var(--dur-fast) var(--ease-out), background var(--dur-fast) var(--ease-out), border-color var(--dur-fast) var(--ease-out);
+}
+.btn:active{transform: translateY(1px)}
+.btn-primary{background: linear-gradient(135deg, var(--primary), var(--primary-strong))}
+.btn-primary:hover{background: linear-gradient(135deg, color-mix(in oklch, var(--primary) 92%, white), color-mix(in oklch, var(--primary-strong) 92%, white))}
+.btn-ghost{
+  background: transparent;
+  color: var(--gb-ink);
+  border-color: color-mix(in oklch, var(--border) 90%, transparent);
+}
+.btn-ghost:hover{background: color-mix(in oklch, var(--surface-2) 80%, transparent)}
+.btn-sm{padding:10px 12px; font-weight:650}
+
+.pill{
+  display:inline-flex; align-items:center; gap:8px;
+  padding:8px 12px;
+  background: color-mix(in oklch, var(--gb-cream) 65%, var(--surface));
+  border:1px solid color-mix(in oklch, var(--gb-cream) 40%, var(--border));
+  border-radius:999px;
+  color: color-mix(in oklch, var(--gb-ink) 88%, var(--gb-brown));
+  font-weight:600;
+  font-size:13px;
+}
+
+.hero{
+  padding: var(--space-7) 0 var(--space-6);
+}
+.hero-grid{
+  display:grid;
+  grid-template-columns: 1.15fr 0.85fr;
+  gap: var(--space-5);
+  align-items:stretch;
+}
+.hero-card{
+  background: color-mix(in oklch, var(--surface) 92%, var(--gb-cream) 8%);
+  border: 1px solid color-mix(in oklch, var(--border) 88%, var(--gb-cream));
+  border-radius: var(--radius-lg);
+  box-shadow: var(--shadow-md);
+  overflow:hidden;
+  position:relative;
+}
+.hero-card::before{
+  content:"";
+  position:absolute; inset:-1px;
+  background: radial-gradient(800px 280px at 20% 0%, oklch(82% 0.12 155 / .55), transparent 60%),
+    radial-gradient(520px 240px at 90% 10%, oklch(88% 0.09 78 / .55), transparent 60%);
+  pointer-events:none;
+}
+.hero-inner{position:relative; padding: var(--space-6)}
+.hero h1{font-size: clamp(36px, 4.4vw, 56px)}
+.hero p.lead{font-size: 18px; color: color-mix(in oklch, var(--gb-ink) 78%, var(--muted)); max-width: 60ch}
+.hero-cta{display:flex; flex-wrap:wrap; gap:10px; margin-top: var(--space-3)}
+
+.hero-media{
+  background:
+    radial-gradient(14px 14px at 20% 20%, oklch(93% 0.06 78), transparent 55%),
+    radial-gradient(20px 20px at 65% 55%, oklch(86% 0.08 155), transparent 58%),
+    linear-gradient(145deg, color-mix(in oklch, var(--gb-brown) 55%, var(--gb-forest)), var(--gb-brown));
+  position:relative;
+  min-height: 340px;
+  display:flex;
+  align-items:flex-end;
+}
+.photo-caption{
+  position:absolute; inset:auto var(--space-4) var(--space-4) var(--space-4);
+  background: color-mix(in oklch, var(--surface) 92%, transparent);
+  border:1px solid color-mix(in oklch, var(--border) 80%, transparent);
+  border-radius: var(--radius-md);
+  padding: var(--space-3);
+  box-shadow: var(--shadow-sm);
+}
+.photo-caption strong{display:block; margin-bottom:6px}
+.photo-caption span{color: var(--muted); font-size: 13px}
+
+.section{padding: var(--space-7) 0}
+.section-tight{padding: var(--space-6) 0}
+.section-head{display:flex; align-items:flex-end; justify-content:space-between; gap: var(--space-3); margin-bottom: var(--space-4)}
+.section-head h2{font-size: clamp(26px, 2.6vw, 34px)}
+.section-head p{max-width: 70ch; color: color-mix(in oklch, var(--gb-ink) 78%, var(--muted))}
+
+.grid-3{
+  display:grid;
+  grid-template-columns: repeat(3, 1fr);
+  gap: var(--space-3);
+}
+.grid-2{
+  display:grid;
+  grid-template-columns: repeat(2, 1fr);
+  gap: var(--space-3);
+}
+
+.card{
+  background: var(--surface);
+  border:1px solid color-mix(in oklch, var(--border) 88%, transparent);
+  border-radius: var(--radius-md);
+  padding: var(--space-4);
+  box-shadow: var(--shadow-sm);
+}
+.card.soft{background: color-mix(in oklch, var(--surface) 92%, var(--gb-mint) 8%)}
+.card .eyebrow{font-size:12px; letter-spacing:0.08em; text-transform:uppercase; color: color-mix(in oklch, var(--muted) 70%, var(--gb-forest)); margin-bottom: 10px}
+.card h3{font-size: 22px}
+.card p{color: color-mix(in oklch, var(--gb-ink) 76%, var(--muted))}
+.card-actions{display:flex; gap:10px; flex-wrap:wrap; margin-top: var(--space-3)}
+
+.kpi-row{display:flex; gap:10px; flex-wrap:wrap; margin-top: var(--space-4)}
+.kpi{background: color-mix(in oklch, var(--surface-2) 70%, transparent); border:1px solid color-mix(in oklch, var(--border) 85%, transparent); padding:10px 12px; border-radius: 999px; font-size: 13px; color: color-mix(in oklch, var(--gb-ink) 78%, var(--muted))}
+
+.page-title{padding: var(--space-6) 0 var(--space-4)}
+.page-title h1{font-size: clamp(30px, 3.6vw, 44px)}
+.page-title p{max-width: 80ch; color: color-mix(in oklch, var(--gb-ink) 78%, var(--muted))}
+
+/* Menu layout */
+.menu-layout{display:grid; grid-template-columns: 320px 1fr; gap: var(--space-4); padding-bottom: var(--space-7)}
+.sidebar{
+  position:sticky; top:86px;
+  height: fit-content;
+  background: color-mix(in oklch, var(--surface) 92%, var(--gb-cream) 8%);
+  border:1px solid color-mix(in oklch, var(--border) 85%, transparent);
+  border-radius: var(--radius-lg);
+  box-shadow: var(--shadow-sm);
+  padding: var(--space-3);
+}
+.sidebar h3{font-size: 18px; margin: 0 0 var(--space-2)}
+.side-group{margin-bottom: var(--space-3)}
+.side-group .label{font-size: 12px; text-transform:uppercase; letter-spacing:0.08em; color: color-mix(in oklch, var(--muted) 70%, var(--gb-forest)); padding: 10px 10px 6px}
+.side-links{display:flex; flex-direction:column; gap: 6px}
+.side-links a{
+  text-decoration:none;
+  padding:10px 10px;
+  border-radius: 12px;
+  color: color-mix(in oklch, var(--gb-ink) 88%, var(--muted));
+}
+.side-links a:hover{background: color-mix(in oklch, var(--surface-2) 75%, transparent)}
+.side-links a.active{background: color-mix(in oklch, var(--primary) 14%, var(--surface)); border:1px solid color-mix(in oklch, var(--primary) 20%, var(--border))}
+
+.menu-grid{display:grid; grid-template-columns: repeat(2, 1fr); gap: var(--space-3)}
+.menu-item{
+  display:flex; gap: var(--space-3);
+  align-items:flex-start;
+  padding: var(--space-3);
+  border:1px solid color-mix(in oklch, var(--border) 85%, transparent);
+  border-radius: var(--radius-md);
+  background: var(--surface);
+}
+.menu-thumb{
+  width:64px; height:64px; border-radius: 16px;
+  background: linear-gradient(135deg, var(--gb-forest), var(--gb-brown-2));
+  position:relative;
+  flex: 0 0 auto;
+  box-shadow: var(--shadow-sm);
+}
+.menu-thumb::after{content:""; position:absolute; inset:10px; border-radius: 999px; background: radial-gradient(circle at 35% 35%, oklch(92% 0.06 78 / .9), transparent 55%), radial-gradient(circle at 70% 70%, oklch(84% 0.08 155 / .75), transparent 60%)}
+.menu-item h4{margin:0 0 6px; font-size: 16px; font-family: Inter, system-ui, sans-serif; letter-spacing:-0.01em}
+.menu-item p{margin:0; font-size: 13px; color: color-mix(in oklch, var(--gb-ink) 76%, var(--muted))}
+
+/* Rewards */
+.tier-grid{display:grid; grid-template-columns: repeat(3, 1fr); gap: var(--space-3)}
+.tier-card{padding: var(--space-4); border-radius: var(--radius-lg)}
+.tier-card .tier{display:flex; justify-content:space-between; align-items:center; gap:10px}
+.badge{font-size:12px; font-weight:750; padding:6px 10px; border-radius:999px; border:1px solid color-mix(in oklch, var(--border) 80%, transparent); background: color-mix(in oklch, var(--surface-2) 75%, transparent)}
+.tier-card ul{margin: var(--space-3) 0 0; padding-left: 18px; color: color-mix(in oklch, var(--gb-ink) 78%, var(--muted))}
+.tier-card li{margin: 8px 0}
+
+.tabs{
+  background: var(--surface);
+  border:1px solid color-mix(in oklch, var(--border) 88%, transparent);
+  border-radius: var(--radius-lg);
+  box-shadow: var(--shadow-sm);
+  overflow:hidden;
+}
+.tablist{
+  display:flex;
+  gap: 6px;
+  padding: 10px;
+  background: color-mix(in oklch, var(--surface-2) 65%, transparent);
+  border-bottom:1px solid color-mix(in oklch, var(--border) 85%, transparent);
+  overflow:auto;
+  scroll-snap-type: x mandatory;
+}
+.tablist button{
+  scroll-snap-align: start;
+  border:1px solid transparent;
+  background: transparent;
+  padding: 10px 12px;
+  border-radius: 999px;
+  font-weight: 700;
+  color: color-mix(in oklch, var(--gb-ink) 82%, var(--muted));
+  cursor:pointer;
+  white-space: nowrap;
+  transition: background var(--dur-fast) var(--ease-out), border-color var(--dur-fast) var(--ease-out), transform var(--dur-fast) var(--ease-out);
+}
+.tablist button[aria-selected="true"]{
+  background: color-mix(in oklch, var(--primary) 16%, var(--surface));
+  border-color: color-mix(in oklch, var(--primary) 22%, var(--border));
+  color: var(--gb-ink);
+}
+.tablist button:active{transform: translateY(1px)}
+.tabpanel{padding: var(--space-4) var(--space-5)}
+.tabpanel .stars{font-size: 14px; color: color-mix(in oklch, var(--muted) 70%, var(--gb-forest)); text-transform:uppercase; letter-spacing:0.08em}
+.tabpanel h3{margin-top: 8px}
+.value-pill{display:inline-flex; align-items:center; gap:8px; background: color-mix(in oklch, var(--gb-cream) 55%, var(--surface)); border:1px solid color-mix(in oklch, var(--gb-cream) 38%, var(--border)); padding: 8px 12px; border-radius: 999px; font-weight:700; color: color-mix(in oklch, var(--gb-ink) 86%, var(--gb-brown))}
+
+/* Carousel */
+.carousel{
+  position:relative;
+  background: var(--surface);
+  border:1px solid color-mix(in oklch, var(--border) 88%, transparent);
+  border-radius: var(--radius-lg);
+  box-shadow: var(--shadow-sm);
+  padding: var(--space-4);
+}
+.carousel-track{
+  display:flex;
+  gap: var(--space-3);
+  overflow:hidden;
+}
+.carousel-slide{
+  min-width: calc((100% - (var(--space-3) * 2)) / 3);
+  flex: 0 0 auto;
+}
+.gift-card{
+  border-radius: var(--radius-md);
+  border:1px solid color-mix(in oklch, var(--border) 85%, transparent);
+  background: linear-gradient(135deg, color-mix(in oklch, var(--primary) 20%, var(--surface)), color-mix(in oklch, var(--gb-cream) 50%, var(--surface)));
+  overflow:hidden;
+  box-shadow: var(--shadow-sm);
+}
+.gift-card .art{
+  height: 140px;
+  background:
+    radial-gradient(26px 26px at 20% 25%, oklch(92% 0.06 78 / .9), transparent 60%),
+    radial-gradient(36px 36px at 78% 65%, oklch(84% 0.08 155 / .8), transparent 60%),
+    linear-gradient(145deg, var(--gb-forest), var(--gb-brown-2));
+}
+.gift-card .meta{padding: 12px 12px 14px}
+.gift-card strong{display:block; font-family: Inter, system-ui, sans-serif; letter-spacing:-0.01em}
+.gift-card span{color: var(--muted); font-size: 12px}
+
+.carousel-nav{
+  position:absolute; top: 16px; right: 16px;
+  display:flex; gap: 8px;
+}
+.icon-btn{
+  width: 42px; height: 42px;
+  border-radius: 999px;
+  border:1px solid color-mix(in oklch, var(--border) 88%, transparent);
+  background: color-mix(in oklch, var(--surface) 88%, transparent);
+  box-shadow: var(--shadow-sm);
+  display:grid; place-items:center;
+  cursor:pointer;
+  transition: transform var(--dur-fast) var(--ease-out), background var(--dur-fast) var(--ease-out);
+}
+.icon-btn:hover{background: color-mix(in oklch, var(--surface-2) 80%, transparent)}
+.icon-btn:active{transform: translateY(1px)}
+.icon{
+  width: 18px; height: 18px; display:block;
+}
+
+/* Store locator */
+.locator{
+  display:grid;
+  grid-template-columns: 420px 1fr;
+  gap: var(--space-4);
+  padding-bottom: var(--space-7);
+}
+.panel{
+  background: var(--surface);
+  border:1px solid color-mix(in oklch, var(--border) 88%, transparent);
+  border-radius: var(--radius-lg);
+  box-shadow: var(--shadow-sm);
+  padding: var(--space-4);
+}
+.field{display:flex; flex-direction:column; gap:8px; margin-bottom: var(--space-3)}
+.field label{font-weight:650; letter-spacing:-0.01em}
+.input{
+  width:100%;
+  padding: 12px 14px;
+  border-radius: 14px;
+  border:1px solid color-mix(in oklch, var(--border) 90%, transparent);
+  background: color-mix(in oklch, var(--surface-2) 60%, transparent);
+  font-size: 16px;
+}
+.input:focus-visible{outline:2px solid color-mix(in oklch, var(--primary) 80%, black); outline-offset:2px}
+.toggle-row{display:flex; gap:10px; flex-wrap:wrap}
+.segmented{
+  display:inline-flex;
+  padding:6px;
+  border-radius: 999px;
+  background: color-mix(in oklch, var(--surface-2) 70%, transparent);
+  border:1px solid color-mix(in oklch, var(--border) 85%, transparent);
+}
+.segmented button{
+  border:0;
+  background: transparent;
+  padding: 10px 12px;
+  border-radius: 999px;
+  cursor:pointer;
+  font-weight: 750;
+  color: color-mix(in oklch, var(--gb-ink) 78%, var(--muted));
+}
+.segmented button[aria-pressed="true"]{
+  background: var(--surface);
+  color: var(--gb-ink);
+  box-shadow: var(--shadow-sm);
+}
+
+.filter-panel{
+  margin-top: var(--space-3);
+  border-top:1px dashed color-mix(in oklch, var(--border) 80%, transparent);
+  padding-top: var(--space-3);
+  display:none;
+}
+.filter-panel[data-open="true"]{display:block}
+.chips{display:flex; flex-wrap:wrap; gap:8px}
+.chip{
+  border:1px solid color-mix(in oklch, var(--border) 88%, transparent);
+  background: color-mix(in oklch, var(--surface-2) 60%, transparent);
+  padding: 8px 10px;
+  border-radius: 999px;
+  font-weight: 650;
+  cursor:pointer;
+}
+.chip[data-active="true"]{background: color-mix(in oklch, var(--primary) 14%, var(--surface)); border-color: color-mix(in oklch, var(--primary) 20%, var(--border))}
+
+.suggestions{
+  position:relative;
+}
+.suggestions-list{
+  position:absolute;
+  inset: calc(100% + 8px) 0 auto 0;
+  z-index: 10;
+  background: var(--surface);
+  border:1px solid color-mix(in oklch, var(--border) 88%, transparent);
+  border-radius: 16px;
+  box-shadow: var(--shadow-md);
+  overflow:hidden;
+  display:none;
+}
+.suggestions-list[data-open="true"]{display:block}
+.suggestions-list button{
+  width:100%;
+  text-align:left;
+  border:0;
+  background: transparent;
+  padding: 12px 12px;
+  cursor:pointer;
+}
+.suggestions-list button:hover{background: color-mix(in oklch, var(--surface-2) 75%, transparent)}
+
+.results{display:flex; flex-direction:column; gap: 10px; margin-top: var(--space-3)}
+.store{
+  border:1px solid color-mix(in oklch, var(--border) 85%, transparent);
+  border-radius: var(--radius-md);
+  padding: var(--space-3);
+  background: color-mix(in oklch, var(--surface) 92%, var(--gb-cream) 8%);
+}
+.store .row{display:flex; justify-content:space-between; gap:10px; align-items:flex-start}
+.store strong{display:block}
+.store small{color: var(--muted)}
+.store .tags{display:flex; gap:6px; flex-wrap:wrap; margin-top: 10px}
+.tag{font-size:12px; padding:6px 10px; border-radius:999px; border:1px solid color-mix(in oklch, var(--border) 85%, transparent); background: color-mix(in oklch, var(--surface) 85%, transparent)}
+
+.map{
+  background:
+    radial-gradient(600px 280px at 25% 20%, oklch(90% 0.07 155 / .6), transparent 65%),
+    radial-gradient(540px 240px at 85% 70%, oklch(90% 0.06 78 / .55), transparent 65%),
+    linear-gradient(145deg, color-mix(in oklch, var(--gb-forest) 55%, var(--gb-brown)), color-mix(in oklch, var(--gb-brown) 85%, black));
+  border-radius: var(--radius-lg);
+  border:1px solid color-mix(in oklch, var(--border) 75%, transparent);
+  box-shadow: var(--shadow-md);
+  min-height: 520px;
+  position:relative;
+  overflow:hidden;
+}
+.map .pin{
+  position:absolute;
+  width: 14px; height: 14px;
