+  .hero-inner{padding: var(--space-5)}
+  .hero p.lead{font-size: 16px}
+  .grid-3{grid-template-columns: 1fr}
+  .grid-2{grid-template-columns: 1fr}
+  .carousel-slide{min-width: 85%}
+  .footer-grid{grid-template-columns: 1fr}
+  .footer-col{border-top:1px solid color-mix(in oklch, var(--border) 85%, transparent)}
+  .footer-col:first-child{border-top:0}
+  .footer-col h4{display:none}
+  .accordion-btn{
+    display:flex;
+    width:100%;
+    align-items:center;
+    justify-content:space-between;
+    gap:12px;
+    padding: 14px 0;
+    background: transparent;
+    border:0;
+    font-weight: 800;
+    letter-spacing:-0.01em;
+    cursor:pointer;
+  }
+  .footer-col[data-open="false"] a{display:none}
+  .footer-col a{padding: 10px 0}
+}
+
+@media (prefers-reduced-motion: reduce){
+  *{scroll-behavior:auto !important}
+  .btn,.tablist button,.icon-btn{transition:none}
+}
+
*** End Patch
PATCH"}

