+  const cols = $all('[data-footer-col]', footer);
+  if (cols.length === 0) return;
+
+  function applyCollapsedState() {
+    const isMobile = window.matchMedia('(max-width: 640px)').matches;
+    cols.forEach((col, idx) => {
+      const btn = $('[data-footer-accordion]', col);
