+  const prev = $('[data-carousel-prev]', root);
+  const next = $('[data-carousel-next]', root);
+  if (!track || !prev || !next) return;
+
+  let index = 0;
+
+  function visibleCount() {
+    const slides = $all('[data-carousel-slide]', track);
+    if (slides.length === 0) return 1;
