+
+    list = list.filter((s) => (activeOrderType === 'pickup' ? s.pickup : s.delivery));
+
+    if (q) {
+      list = list.filter((s) => normalize(s.name).includes(q) || normalize(s.address).includes(q));
+    }
+
+    if (activeChips.size > 0) {
+      list = list.filter((s) => {
